// Tillis Auto Aesthetics checkout helper (Cloudflare Worker).
// GENERATED by build_static.py from pricing.py. Do not edit prices here.
// Secret needed in Cloudflare: STRIPE_SECRET_KEY. Optional: STRIPE_TAX_ENABLED = "true".
const PRICING = __PRICING__;
const SITE = "__SITE__";
const ALLOWED = ["https://tillis.autos", "https://www.tillis.autos"];

const r5 = (x) => Math.round(x / 5) * 5;
const cors = (origin) => ({
  "Access-Control-Allow-Origin": ALLOWED.includes(origin) || /^http:\/\/(localhost|127\.0\.0\.1)(:\d+)?$/.test(origin || "") ? origin : SITE,
  "Access-Control-Allow-Methods": "POST, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type",
  "Vary": "Origin",
});
const json = (obj, status, origin) =>
  new Response(JSON.stringify(obj), { status, headers: { "Content-Type": "application/json", ...cors(origin) } });

// --- 70/30 split (Stripe Connect) -------------------------------------------------
// Cloudflare text variable DETAILERS_JSON maps a city to a detailer's connected account, for example
//   {"Torrance":"acct_123","Redondo Beach":"acct_123","Gardena":"acct_456","default":"acct_123"}
// If a city has no detailer (and there is no "default"), the booking is NOT split: you receive all of it.
// Cloudflare text variable DETAILER_PERCENT (default 70) is the detailer's share.
function detailerFor(city, env) {
  try {
    const map = JSON.parse(env.DETAILERS_JSON || "{}");
    const id = map[city] || map["default"];
    return typeof id === "string" && id.startsWith("acct_") ? id : null;
  } catch { return null; }
}
const detailerPercent = (env) => {
  const n = Number(env.DETAILER_PERCENT);
  return n > 0 && n < 100 ? n : 70;
};

function buildSession(b, env, split = true) {
  const P = PRICING;
  const vehicle = String(b.vehicle || ""), cond = String(b.condition || ""), pkg = String(b.package || "");
  if (!P.vehicles[vehicle]) throw new Error("Choose your vehicle size");
  const meta = {
    vehicle, condition: P.conditions[cond] ? cond : "", city: String(b.city || "").slice(0, 60),
    address: String(b.address || "").slice(0, 200), date: String(b.date || "").slice(0, 60), notes: String(b.notes || "").slice(0, 300),
  };
  let mode = "payment";
  let trialDays = 0;
  const oneTime = []; // charged today
  const recurring = []; // monthly plan
  if (pkg === "plan") {
    // Individuals must do a Revival first; the monthly plan starts after it.
    const rev = P.membership.requires;
    if (!P.conditions[cond]) throw new Error("Choose how dirty the vehicle is (needed for your Revival)");
    mode = "subscription";
    trialDays = P.membership.trial_days;
    meta.package = "plan+" + rev;
    oneTime.push([`${P.packages[rev].name} - ${P.vehicles[vehicle]} (${P.conditions[cond].label.toLowerCase()})`,
      r5(P.packages[rev].prices[vehicle] * P.conditions[cond].mult)]);
    recurring.push([`${P.membership.name} - ${P.vehicles[vehicle]} (${P.membership.discount_pct}% recurring rate)`, P.membership.prices[vehicle]]);
  } else {
    if (!P.packages[pkg] || !P.conditions[cond]) throw new Error("Choose a package and how dirty the vehicle is");
    meta.package = pkg;
    oneTime.push([`${P.packages[pkg].name} - ${P.vehicles[vehicle]} (${P.conditions[cond].label.toLowerCase()})`,
      r5(P.packages[pkg].prices[vehicle] * P.conditions[cond].mult)]);
    for (const a of Array.isArray(b.addons) ? b.addons : []) {
      if (P.addons[a] && !(pkg === "premium" && P.premium_includes.includes(a)) && !oneTime.some((l) => l[0] === P.addons[a].name))
        oneTime.push([P.addons[a].name, P.addons[a].price]);
    }
  }
  const f = new URLSearchParams();
  f.set("mode", mode);
  if (b.embedded) {
    f.set("ui_mode", "embedded_page");
    f.set("return_url", `${SITE}/thanks/?session_id={CHECKOUT_SESSION_ID}`);
  } else {
    f.set("success_url", `${SITE}/thanks/`);
    f.set("cancel_url", `${SITE}/book/`);
  }
  f.set("phone_number_collection[enabled]", "true");
  f.set("billing_address_collection", "required");
  if (mode === "payment") f.set("invoice_creation[enabled]", "true");
  if (env.STRIPE_TAX_ENABLED === "true") f.set("automatic_tax[enabled]", "true");
  let i = 0;
  const addLine = (name, dollars, isRecurring) => {
    const p = `line_items[${i++}]`;
    f.set(`${p}[quantity]`, "1");
    f.set(`${p}[price_data][currency]`, "usd");
    f.set(`${p}[price_data][unit_amount]`, String(Math.round(dollars * 100)));
    f.set(`${p}[price_data][product_data][name]`, name);
    f.set(`${p}[price_data][product_data][tax_code]`, "txcd_20030000");
    if (isRecurring) f.set(`${p}[price_data][recurring][interval]`, "month");
  };
  oneTime.forEach(([n, d]) => addLine(n, d, false));
  recurring.forEach(([n, d]) => addLine(n, d, true));
  if (trialDays) f.set("subscription_data[trial_period_days]", String(trialDays));
  // Split the payment with the detailer for this city (Stripe Connect destination charge)
  const wanted = detailerFor(meta.city, env);
  const detailer = split ? wanted : null;
  if (!split && wanted) meta.split_skipped = "detailer account not ready, booked without split";
  if (detailer) {
    const pct = detailerPercent(env);
    meta.detailer = detailer;
    if (mode === "subscription") {
      f.set("subscription_data[transfer_data][destination]", detailer);
      f.set("subscription_data[transfer_data][amount_percent]", String(pct));
    } else {
      const subtotalCents = oneTime.reduce((t, [, d]) => t + Math.round(d * 100), 0);
      f.set("payment_intent_data[transfer_data][destination]", detailer);
      f.set("payment_intent_data[transfer_data][amount]", String(Math.round((subtotalCents * pct) / 100)));
    }
  }
  for (const [k, v] of Object.entries(meta)) {
    f.set(`metadata[${k}]`, v);
    if (mode === "subscription") f.set(`subscription_data[metadata][${k}]`, v);
  }
  return f;
}

export default {
  async fetch(req, env) {
    const origin = req.headers.get("Origin") || "";
    if (req.method === "OPTIONS") return new Response(null, { status: 204, headers: cors(origin) });
    if (req.method !== "POST") return json({ error: "POST only" }, 405, origin);
    let body;
    try { body = await req.json(); } catch { return json({ error: "Bad request" }, 400, origin); }
    let form;
    try { form = buildSession(body, env, true); } catch (e) { return json({ error: e.message }, 400, origin); }
    const call = (f) => fetch("https://api.stripe.com/v1/checkout/sessions", {
      method: "POST",
      headers: { Authorization: `Bearer ${env.STRIPE_SECRET_KEY}`, "Content-Type": "application/x-www-form-urlencoded" },
      body: f,
    });
    let r = await call(form);
    if (!r.ok && form.has("metadata[detailer]")) {
      // The detailer account may not be ready to receive money yet. Book without the split rather than lose the sale.
      r = await call(buildSession(body, env, false));
    }
    const s = await r.json();
    if (!r.ok) return json({ error: "Could not start checkout", detail: (s.error && s.error.message) || r.status }, 502, origin);
    return json({ url: s.url, clientSecret: s.client_secret, publishableKey: env.STRIPE_PUBLISHABLE_KEY || null }, 200, origin);
  },
};
